#include <vector>

using namespace std;

class Solution {
public:
    int numRookCaptures(vector<vector<char>>& board) {
        int x, y;
        for (int i = 0; i < 8; ++i)
            for (int j = 0; j < 8; ++j)
                if (board[i][j] == 'R') {
                    x = i; y = j;
                }
        int res = 0, dirs[5] = {0, 1, 0, -1, 0};
        for (int d = 0; d < 4; ++d) {
            int nx = x, ny = y;
            while (true) {
                nx += dirs[d]; ny += dirs[d + 1];
                if (nx < 0 || ny < 0 || nx >= 8 || ny >= 8 || board[nx][ny] == 'B') break;
                if (board[nx][ny] == 'p') {
                    res++;
                    break;
                }
            }
        }
        return res;
    }
};
